#!/usr/bin/env python3
import sys, re, zipfile, shutil, os

IN_DOCX = 'inputs/offer_letter_template.docx'
DATA_JSON = 'inputs/employee_data.json'
OUT_DOCX = 'output/offer_letter_filled.docx'

import json
with open(DATA_JSON, encoding='utf-8') as f:
    data = json.load(f)

PLACEHOLDER_RE = re.compile(r'\{\{([A-Z0-9_]+)\}\}')
COND_RE = re.compile(r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}', re.S)

errors = []

def xml_escape(s):
    return (s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))

def resolve_conditionals(text, part):
    """Apply IF_RELOCATION conditional. Only RELOCATION_PACKAGE governs."""
    def repl(m):
        if 'RELOCATION_PACKAGE' not in data:
            errors.append(f"{part}: conditional present but governing field RELOCATION_PACKAGE is missing")
            return ''  # placeholder; nonzero exit handled later
        gov = data['RELOCATION_PACKAGE']
        return m.group(1) if gov == 'Yes' else ''
    return COND_RE.sub(repl, text)

def resolve_placeholders(text, part):
    def repl(m):
        name = m.group(1)
        if name in ('IF_RELOCATION', 'END_IF_RELOCATION'):
            # should have been consumed by conditional; leftover => malformed
            errors.append(f"{part}: unmatched conditional marker {{{{{name}}}}}")
            return m.group(0)
        if name not in data:
            errors.append(f"{part}: required field {name} is missing")
            return m.group(0)
        return xml_escape(str(data[name]))
    return PLACEHOLDER_RE.sub(repl, text)

def process_paragraph(para_xml, part):
    # Collect <w:t ...>...</w:t> occurrences
    t_re = re.compile(r'(<w:t\b[^>]*>)(.*?)(</w:t>)', re.S)
    matches = list(t_re.finditer(para_xml))
    if not matches:
        return para_xml
    merged = ''.join(m.group(2) for m in matches)
    # unescape for logic matching (only entities that matter for token detection)
    unesc = merged.replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>')
    if '{{' not in unesc:
        return para_xml
    new = resolve_conditionals(unesc, part)
    new = resolve_placeholders(new, part)
    # re-escape whole result for XML text node
    new_escaped = xml_escape(new)
    # Put entire new text into the first <w:t>; empty the rest.
    out = []
    last = 0
    for i, m in enumerate(matches):
        out.append(para_xml[last:m.start()])
        open_tag = m.group(1)
        # ensure xml:space preserve on the carrying run to keep spacing
        if i == 0:
            if 'xml:space' not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            out.append(open_tag + new_escaped + m.group(3))
        else:
            out.append(open_tag + m.group(3))
        last = m.end()
    out.append(para_xml[last:])
    return ''.join(out)

def process_part(content, part):
    # Split into paragraphs, process each, reassemble preserving everything else.
    p_re = re.compile(r'(<w:p\b[^>]*>.*?</w:p>|<w:p\b[^>]*/>)', re.S)
    def repl(m):
        return process_paragraph(m.group(0), part)
    return p_re.sub(repl, content)

zin = zipfile.ZipFile(IN_DOCX, 'r')
targets = set(n for n in zin.namelist()
              if n == 'word/document.xml'
              or re.match(r'word/(header|footer)\d+\.xml$', n))

os.makedirs(os.path.dirname(OUT_DOCX), exist_ok=True)
# Build in memory first, so we only write if no errors.
new_contents = {}
for n in zin.namelist():
    raw = zin.read(n)
    if n in targets:
        txt = raw.decode('utf-8')
        new_contents[n] = process_part(txt, n).encode('utf-8')
    else:
        new_contents[n] = raw

if errors:
    for e in errors:
        print("ERROR:", e, file=sys.stderr)
    sys.exit(1)

zout = zipfile.ZipFile(OUT_DOCX, 'w', zipfile.ZIP_DEFLATED)
for n in zin.namelist():
    info = zin.getinfo(n)
    zout.writestr(info, new_contents[n])
zout.close()
zin.close()
print("Wrote", OUT_DOCX)

